import type { Prisma } from "@/generated/prisma/client";
// Internal entitlement metadata. Only userDto() crosses the server boundary.
export const adminUserSelect = {
  id: true,
  email: true,
  name: true,
  createdAt: true,
  plan: true,
  subscriptionStatus: true,
  currentPeriodStart: true,
  currentPeriodEnd: true,
  dodoSubscriptionId: true,
  gracePeriodEnd: true,
  cancelAtPeriodEnd: true,
  planOverride: true,
  planOverrideStartsAt: true,
  planOverrideExpiresAt: true,
  grandfatheredUntil: true,
  isSuspended: true,
  suspendedAt: true,
  deletionRequestedAt: true,
  gmailAuthorized: true,
  lastActiveAt: true,
  usageBackfillVersion: true,
  usageCutoverAt: true,
} satisfies Prisma.UserSelect;
export type AdminUser = Prisma.UserGetPayload<{
  select: typeof adminUserSelect;
}>;
export const reservationSelect = {
  userId: true,
  deliveryKey: true,
  dailyPeriodId: true,
  monthlyPeriodId: true,
  status: true,
  chargedAt: true,
} as const;
export const evidenceSelect = {
  userId: true,
  deliveryKey: true,
  chargedAt: true,
} as const;
